const webhookData = $('Receive Transcription Request').first().json;

// ─── Security: verify X-N8N-Secret header ─────────────────────────────
const receivedSecret = webhookData.headers?.['x-n8n-secret']
                    || webhookData.headers?.['X-N8N-Secret']
                    || '';
const expectedSecret = 'change-me-in-production';

if (receivedSecret !== expectedSecret) {
  throw new Error('401: Invalid X-N8N-Secret header.');
}

// ─── Extract body ──────────────────────────────────────────────────────
const body = webhookData.body || webhookData;

const messageId      = body.message_id;
const conversationId = body.conversation_id;
const audioUrl       = body.audio_url;
const language       = body.language || 'fr';

if (!messageId || !conversationId || !audioUrl) {
  throw new Error('400: Missing required fields: message_id, conversation_id, audio_url');
}

return [{
  json: {
    messageId,
    conversationId,
    audioUrl,
    language,
    laravelUrl: 'http://nginx:80',
    n8nSecret:  'change-me-in-production',
    groqModel:  'whisper-large-v3',
  }
}];

const whisperReply = $input.first().json;
const prevData     = $('Validate Auth & Extract Payload').first().json;

// ─── Groq Whisper returns { text, language, duration, segments, ... } ──
const transcription = String(whisperReply.text || '').trim();
const duration      = Number(whisperReply.duration || 0);
const language      = whisperReply.language || prevData.language || 'fr';

if (!transcription) {
  // Don't crash — send back an empty transcription so Laravel can handle gracefully
  return [{
    json: {
      callbackPayload: {
        message_id:      prevData.messageId,
        conversation_id: prevData.conversationId,
        transcription:   '',
        language,
        model:           prevData.groqModel,
        duration:        0,
        success:         false,
      },
      laravelUrl: prevData.laravelUrl,
      n8nSecret:  prevData.n8nSecret,
    }
  }];
}

return [{
  json: {
    callbackPayload: {
      message_id:      prevData.messageId,
      conversation_id: prevData.conversationId,
      transcription,
      language,
      model:           prevData.groqModel,
      duration,
      success:         true,
    },
    laravelUrl: prevData.laravelUrl,
    n8nSecret:  prevData.n8nSecret,
  }
}];
